// scripts/bundle-readability.js
// Concatenates @mozilla/readability into a single file for content script use.
// Content scripts loaded via manifest.json "js" array cannot use ES/CommonJS modules.

const fs = require('fs');
const path = require('path');

const pkg = 'node_modules/@mozilla/readability';

const jsdomParser = fs.readFileSync(path.join(pkg, 'JSDOMParser.js'), 'utf8');
const readability = fs.readFileSync(path.join(pkg, 'Readability.js'), 'utf8');
const readerable = fs.readFileSync(path.join(pkg, 'Readability-readerable.js'), 'utf8');

// Remove CommonJS exports from JSDOMParser
const jsdomParserClean = jsdomParser.replace(/module\.exports\s*=\s*JSDOMParser;?/, '');

// Remove CommonJS exports from Readability-readerable
const readerableClean = readerable.replace(/module\.exports\s*=\s*isProbablyReaderable;?/, '');

const bundle = `// Generated by scripts/bundle-readability.js — do not edit directly.
// Source: @mozilla/readability (npm)
(function() {
${jsdomParserClean}

${readability}

${readerableClean}

// Expose to global scope for content_script.js
window.Readability = Readability;
window.isProbablyReaderable = isProbablyReaderable;
})();
`;

const outPath = 'src/content/readability-bundle.js';
fs.writeFileSync(outPath, bundle);
console.log(`Bundle written to ${outPath} (${(bundle.length / 1024).toFixed(1)} KB)`);
